class Solution {
    public boolean canPartition(int[] nums) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if (total % 2 != 0) {
            return false;
        }

        int target = total / 2;
        boolean[][] dp = new boolean[nums.length + 1][target + 1];
        dp[0][0] = true;

        for (int index = 1; index <= nums.length; index++) {
            int num = nums[index - 1];
            for (int sum = 0; sum <= target; sum++) {
                boolean skip = dp[index - 1][sum];
                boolean take = sum >= num && dp[index - 1][sum - num];
                dp[index][sum] = skip || take;
            }
        }
        return dp[nums.length][target];
    }
}

class Solution {
    public boolean canPartition(int[] nums) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if ((total & 1) == 1) {
            return false;
        }

        int target = total / 2;
        Boolean[][] memo = new Boolean[nums.length][target + 1];
        return canFill(nums, 0, target, memo);
    }

    private boolean canFill(int[] nums, int index, int remaining, Boolean[][] memo) {
        if (remaining == 0) {
            return true;
        }
        if (index == nums.length || remaining < 0) {
            return false;
        }
        if (memo[index][remaining] != null) {
            return memo[index][remaining];
        }

        boolean skip = canFill(nums, index + 1, remaining, memo);
        boolean take = canFill(nums, index + 1, remaining - nums[index], memo);
        memo[index][remaining] = skip || take;
        return memo[index][remaining];
    }
}

class Solution {
    public boolean canPartition(int[] nums) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if (total % 2 != 0) {
            return false;
        }

        int target = total / 2;
        java.math.BigInteger reachable = java.math.BigInteger.ONE;
        for (int num : nums) {
            reachable = reachable.or(reachable.shiftLeft(num));
            if (reachable.testBit(target)) {
                return true;
            }
        }
        return reachable.testBit(target);
    }
}

class Solution {
    public boolean canPartition(int[] nums) {
        int total = 0;
        for (int num : nums) {
            total += num;
        }
        if ((total & 1) == 1) {
            return false;
        }

        int target = total / 2;
        java.util.Set<Integer> reachable = new java.util.HashSet<>();
        reachable.add(0);

        for (int num : nums) {
            java.util.Set<Integer> next = new java.util.HashSet<>(reachable);
            for (int sum : reachable) {
                int candidate = sum + num;
                if (candidate == target) {
                    return true;
                }
                if (candidate < target) {
                    next.add(candidate);
                }
            }
            reachable = next;
        }
        return reachable.contains(target);
    }
}
